import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import Layout from "./components/Layout";
import Home from "./components/Home";
import Favourite from "./components/Favourites";
import React, { useState } from "react";
import './index.css';

function App() {
  const [songs, setSongs] = useState([
    { 
      id: "1", 
      name: "Bohemian Rhapsody", 
      artist: "Queen", 
      liked: false,
      cover: "https://upload.wikimedia.org/wikipedia/en/9/9f/Bohemian_Rhapsody.png"
    },
    { 
      id: "2", 
      name: "Stairway to Heaven", 
      artist: "Led Zeppelin", 
      liked: false,
      cover: "data:image/jpeg;base64,"
    },
    { 
      id: "3", 
      name: "Hotel California", 
      artist: "Eagles", 
      liked: false,
      cover: "https://upload.wikimedia.org/wikipedia/en/4/49/Hotelcalifornia.jpg"
    },
    { 
      id: "4", 
      name: "Sweet Child O'Mine", 
      artist: "Guns N' Roses", 
      liked: false,
      cover: "data:image/jpeg;base64,"
    },
    { 
      id: "5", 
      name: "Smells Like Teen Spirit", 
      artist: "Nirvana", 
      liked: false,
      cover: "https://upload.wikimedia.org/wikipedia/en/b/b7/NirvanaNevermindalbumcover.jpg"
    },
    { 
      id: "6", 
      name: "Imagine", 
      artist: "John Lennon", 
      liked: false,
      cover: "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQtXSf-r-fboyVz-XH3V1Vj69Wx9ZI5lx211A&s"
    },
    { 
      id: "7", 
      name: "Billie Jean", 
      artist: "Michael Jackson", 
      liked: false,
      cover: "data:image/jpeg;base64,"
    },
    { 
      id: "8", 
      name: "Like a Rolling Stone", 
      artist: "Bob Dylan", 
      liked: false,
      cover: "data:image/jpeg;base64,"
    },
    { 
      id: "9", 
      name: "Purple Haze", 
      artist: "Jimi Hendrix", 
      liked: false,
      cover: "data:image/jpeg;base64, "
    },
    { 
      id: "10", 
      name: "Respect", 
      artist: "Aretha Franklin", 
      liked: false,
      cover: "data:image/jpeg;base64,"
    },
  ]);

  const toggleLike = (id) => {
    setSongs(
      songs.map((song) =>
        song.id === id ? { ...song, liked: !song.liked } : song
      )
    );
  };

  return (
    <Router>
      <Layout>
        <Routes>
          <Route 
            path="/" 
            element={<Home songs={songs} onToggleLike={toggleLike} />} 
          />
          <Route 
            path="/favourite" 
            element={<Favourite songs={songs} onToggleLike={toggleLike} />} 
          />
        </Routes>
      </Layout>
    </Router>
  );
}

export default App;
